import React, { useEffect, useRef, useState } from 'react';
import { ExternalLink, Github, Eye, ArrowUpRight, Sparkles } from 'lucide-react';
import { useAuth } from '../context/AuthContext';

const defaultProjects = [
  {
    title: 'E-Commerce Platform',
    category: 'Web Development',
    description: 'A full-featured online store with secure payment processing, inventory management, and real-time order tracking.',
    image: 'https://images.unsplash.com/photo-1556742049-0cfed4f6a45d?w=800&h=600&fit=crop',
    tech: ['React.js', 'Node.js', 'MySQL', 'Stripe'],
    demoLink: '#',
    codeLink: '#',
    featured: true
  },
  {
    title: 'Learning Management System',
    category: 'System Development',
    description: 'Comprehensive LMS for educational institutions with course management, student tracking, and assessment tools.',
    image: 'https://images.unsplash.com/photo-1501504905252-473c47e087f8?w=800&h=600&fit=crop',
    tech: ['PHP', 'MySQL', 'JavaScript', 'Bootstrap'],
    demoLink: '#',
    codeLink: '#',
    featured: false
  },
  {
    title: 'Corporate Dashboard',
    category: 'UI/UX Design',
    description: 'Modern analytics dashboard with data visualization, real-time metrics, and customizable widgets.',
    image: 'https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=800&h=600&fit=crop',
    tech: ['React.js', 'Tailwind CSS', 'Chart.js', 'REST API'],
    demoLink: '#',
    codeLink: '#',
    featured: true
  },
  {
    title: 'Restaurant Booking App',
    category: 'Web Development',
    description: 'Online reservation system with table management, menu display, and customer notifications.',
    image: 'https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?w=800&h=600&fit=crop',
    tech: ['React.js', 'PHP', 'MySQL', 'Twilio'],
    demoLink: '#',
    codeLink: '#',
    featured: false
  },
  {
    title: 'Portfolio Generator',
    category: 'Web Development',
    description: 'Dynamic portfolio builder allowing users to create and customize their professional portfolios.',
    image: 'https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=800&h=600&fit=crop',
    tech: ['React.js', 'Firebase', 'Tailwind CSS'],
    demoLink: '#',
    codeLink: '#',
    featured: false
  },
  {
    title: 'Healthcare Portal',
    category: 'System Development',
    description: 'Patient management system with appointment scheduling, medical records, and prescription tracking.',
    image: 'https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800&h=600&fit=crop',
    tech: ['PHP', 'MySQL', 'JavaScript', 'HTML5'],
    demoLink: '#',
    codeLink: '#',
    featured: true
  }
];

const categories = ['All', 'Web Development', 'System Development', 'UI/UX Design'];

const Portfolio = () => {
  const sectionRef = useRef(null);
  const [activeFilter, setActiveFilter] = useState('All');
  const [projects, setProjects] = useState([]);

  useEffect(() => {
    fetch(`${API_URL}/projects.php`)
      .then(res => res.json())
      .then(data => {
        if (data.length > 0) {
          setProjects(data.map(p => ({
            title: p.title,
            category: p.category,
            description: p.description,
            image: p.image_url,
            tech: [],
            demoLink: p.project_url,
            codeLink: '#',
            featured: false
          })));
        } else {
          setProjects(defaultProjects);
        }
      })
      .catch(err => {
        console.error('Error fetching projects:', err);
        setProjects(defaultProjects);
      });
  }, []);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('active');
          }
        });
      },
      { threshold: 0.1, rootMargin: '0px 0px -50px 0px' }
    );

    const reveals = sectionRef.current?.querySelectorAll('.reveal');
    reveals?.forEach((el) => observer.observe(el));

    return () => observer.disconnect();
  }, []);

  const filteredProjects = activeFilter === 'All' 
    ? (projects.length > 0 ? projects : defaultProjects) 
    : (projects.length > 0 ? projects : defaultProjects).filter(p => p.category === activeFilter);

  return (
    <section id="portfolio" ref={sectionRef} className="py-24 bg-[#0a1628] relative overflow-hidden">
      {/* Background elements */}
      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[1000px] h-[1000px] bg-blue-500/5 rounded-full blur-3xl"></div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
        {/* Section Header */}
        <div className="text-center mb-12 reveal">
          <span className="inline-block px-4 py-2 rounded-full bg-blue-500/10 text-blue-400 text-sm font-medium mb-4">
            Our Work
          </span>
          <h2 className="text-4xl sm:text-5xl font-bold text-white mb-6">
            Featured <span className="gradient-text">Projects</span>
          </h2>
          <p className="text-gray-400 max-w-2xl mx-auto text-lg">
            Explore our portfolio of successful projects that showcase our expertise 
            and commitment to delivering exceptional results.
          </p>
        </div>

        {/* Filter Buttons */}
        <div className="flex flex-wrap justify-center gap-3 mb-12 reveal">
          {categories.map((category) => (
            <button
              key={category}
              onClick={() => setActiveFilter(category)}
              className={`px-5 py-2 rounded-full text-sm font-medium transition-all duration-300 ${
                activeFilter === category
                  ? 'bg-gradient-to-r from-blue-600 to-purple-600 text-white shadow-lg shadow-blue-500/25'
                  : 'glass text-gray-400 hover:text-white hover:bg-white/10'
              }`}
            >
              {category}
            </button>
          ))}
        </div>

        {/* Featured Projects (when showing All) */}
        {activeFilter === 'All' && (
          <div className="mb-12 reveal">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
              {(projects.length > 0 ? filteredProjects.filter(p => p.featured) : defaultProjects.filter(p => p.featured)).slice(0, 2).map((project, index) => (
                <div
                  key={project.title}
                  className="group relative"
                  style={{ transitionDelay: `${index * 100}ms` }}
                >
                  <div className="card-minimal rounded-3xl overflow-hidden h-full">
                    <div className="relative h-64 overflow-hidden">
                      <img
                        src={project.image}
                        alt={project.title}
                        className="w-full h-full object-cover transform group-hover:scale-105 transition-transform duration-700"
                      />
                      <div className="absolute inset-0 bg-gradient-to-t from-navy-950 via-navy-950/70 to-transparent"></div>

                      {/* Featured Badge */}
                      <div className="absolute top-4 left-4 px-3 py-1.5 rounded-full bg-gradient-to-r from-yellow-500 to-orange-500 text-white text-xs font-bold flex items-center gap-1">
                        <Sparkles className="w-3 h-3" />
                        Featured
                      </div>

                      {/* Hover overlay */}
                      <div className="absolute inset-0 bg-blue-500/20 opacity-0 group-hover:opacity-100 transition-opacity duration-300" />

                      {/* Links */}
                      <div className="absolute top-4 right-4 flex gap-2 opacity-0 group-hover:opacity-100 transform translate-y-2 group-hover:translate-y-0 transition-all duration-300">
                        <a href={project.demoLink} className="w-10 h-10 rounded-full bg-white/20 backdrop-blur-sm flex items-center justify-center text-white hover:bg-white/30 transition-colors">
                          <Eye className="w-4 h-4" />
                        </a>
                        <a href={project.codeLink} className="w-10 h-10 rounded-full bg-white/20 backdrop-blur-sm flex items-center justify-center text-white hover:bg-white/30 transition-colors">
                          <Github className="w-4 h-4" />
                        </a>
                      </div>

                      {/* Bottom content overlay */}
                      <div className="absolute bottom-0 left-0 right-0 p-6">
                        <span className="text-xs font-medium text-blue-400 mb-2 block">{project.category}</span>
                        <h3 className="text-2xl font-bold text-white mb-2 group-hover:text-blue-400 transition-colors">
                          {project.title}
                        </h3>
                        <p className="text-gray-300 text-sm mb-4 line-clamp-2">{project.description}</p>

                        <div className="flex flex-wrap gap-2">
                          {project.tech.slice(0, 3).map((tech) => (
                            <span key={tech} className="px-2 py-1 rounded-md text-xs font-medium bg-white/10 text-white border border-white/20">
                              {tech}
                            </span>
                          ))}
                          {project.tech.length > 3 && (
                            <span className="px-2 py-1 rounded-md text-xs font-medium text-gray-400">
                              +{project.tech.length - 3}
                            </span>
                          )}
                        </div>
                      </div>

                      {/* Arrow */}
                      <div className="absolute bottom-6 right-6 w-12 h-12 rounded-full bg-white flex items-center justify-center opacity-0 group-hover:opacity-100 transform translate-y-4 group-hover:translate-y-0 transition-all duration-300">
                        <ArrowUpRight className="w-5 h-5 text-navy-950" />
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Projects Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {((projects.length > 0 ? projects : defaultProjects).length > 0 ? (activeFilter === 'All' ? (projects.length > 0 ? filteredProjects.filter(p => !p.featured) : defaultProjects.filter(p => !p.featured)) : filteredProjects) : []).map((project, index) => (
            <div
              key={project.title}
              className="reveal group"
              style={{ transitionDelay: `${index * 100}ms` }}
            >
              <div className="card-minimal rounded-2xl overflow-hidden h-full flex flex-col">
                {/* Image Container */}
                <div className="relative h-48 overflow-hidden">
                  <img
                    src={project.image}
                    alt={project.title}
                    className="w-full h-full object-cover transform group-hover:scale-110 transition-transform duration-500"
                  />
                  {/* Overlay */}
                  <div className="absolute inset-0 bg-gradient-to-t from-navy-950 via-navy-950/50 to-transparent opacity-60"></div>

                  {/* Hover Links */}
                  <div className="absolute inset-0 flex items-center justify-center gap-4 opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                    <a
                      href={project.demoLink}
                      className="w-12 h-12 rounded-full bg-white/20 backdrop-blur-sm flex items-center justify-center text-white hover:bg-white/30 transition-colors transform hover:scale-110"
                    >
                      <Eye className="w-5 h-5" />
                    </a>
                    <a
                      href={project.codeLink}
                      className="w-12 h-12 rounded-full bg-white/20 backdrop-blur-sm flex items-center justify-center text-white hover:bg-white/30 transition-colors transform hover:scale-110"
                    >
                      <Github className="w-5 h-5" />
                    </a>
                  </div>
                </div>

                {/* Content */}
                <div className="p-6 flex-grow flex flex-col">
                  <span className="text-xs font-medium text-blue-400 mb-2">{project.category}</span>
                  <h3 className="text-xl font-bold text-white mb-2 group-hover:text-blue-400 transition-colors">
                    {project.title}
                  </h3>
                  <p className="text-gray-400 text-sm mb-4 leading-relaxed flex-grow line-clamp-3">
                    {project.description}
                  </p>

                  {/* Tech Stack */}
                  <div className="flex flex-wrap gap-2">
                    {project.tech.slice(0, 3).map((tech) => (
                      <span
                        key={tech}
                        className="px-2 py-1 rounded-md text-xs font-medium bg-white/5 text-gray-300 border border-white/10"
                      >
                        {tech}
                      </span>
                    ))}
                    {project.tech.length > 3 && (
                      <span className="px-2 py-1 rounded-md text-xs font-medium text-gray-500">
                        +{project.tech.length - 3}
                      </span>
                    )}
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* View More CTA */}
        <div className="text-center mt-12 reveal">
          <a
            href="#contact"
            className="inline-flex items-center gap-2 px-6 py-3 glass text-white font-medium rounded-xl hover:bg-white/10 transition-all duration-300 group"
          >
            Want to see more?
            <span className="text-blue-400 group-hover:underline">Let&apos;s collaborate</span>
            <ExternalLink className="w-4 h-4" />
          </a>
        </div>
      </div>
    </section>
  );
};

export default Portfolio;
